import pages, runpy
from pages import reading as R
from fig2 import *
from fig import svg
E=pages.EXTRA
def F(label,items,labels=(),bg='#fffaf0',gy=160): return fig_row(label,items,labels,bg=bg,gy=gy)
VY=lambda: sage('#ff8c1a')
G='/festivals/guru-purnima/'
E[G+'vyasa-purnima/']=[
 R('veda','DIVIDING THE VEDA','Why Vyāsa is “the arranger”',F('One book becoming four',[(book(),1.6),('<path d="M-30 0 h60" stroke="#111" stroke-width="3"/><path d="M30 0 l-8 -5 v10z" fill="#111"/>',1),(''.join(f'<g transform="translate({-36+k*24} 0) scale(.5)">{book()}</g>' for k in range(4)),1.4)],['one Veda','','four Vedas']),['<b>One into four.</b> Tradition says that at the start of this age the Veda was one great body; seeing that people of the coming age could not hold it all, Vyāsa divided it into four.','<b>Four disciples.</b> He taught the Ṛg Veda to Paila, the Yajur to Vaiśampāyana, the Sāma to Jaimini and the Atharva to Sumantu.','<b>A title.</b> “Vyāsa” is also a title: the Purāṇas name a Vyāsa for each age; Kṛṣṇa Dvaipāyana is the Vyāsa of ours.','<b>Teachers’ day.</b> Because the whole Vedic tradition flows through his disciples, his birthday became the day of all teachers.'],[('z','So every Vedic school traces back to Vyāsa?'),('b','Through those four disciples, by tradition. That is why priests honour him first.')],'One Veda, four disciples: <b>Vyāsa the arranger</b>.'),
 R('mahabharata','THE MAHĀBHĀRATA','The fifth Veda',F('A huge stack of palm-leaf books',[(books_stack(),2.4)],['the epic']),['<b>The longest poem.</b> The Mahābhārata, attributed to Vyāsa, runs to about a hundred thousand verses, the longest epic poem in the world.','<b>Fifth Veda.</b> It calls itself the fifth Veda: knowledge for everyone, including those not taught the Vedas.','<b>The Gītā inside.</b> The Bhagavad Gītā is part of its Bhīṣma Parva; see our <a href="/vishnu/bhagavad-gita/">Gītā series</a>.','<b>His own story.</b> Vyāsa appears in it as grandfather of the Kauravas and Pāṇḍavas, and as a guide at key moments.'],[('z','He wrote about his own grandchildren?'),('b','Composed it, by tradition. He was both author and character. Very unusual.')],'The Mahābhārata: <b>the fifth Veda</b>.'),
 R('purana','THE PURĀṆAS AND THE BRAHMA SŪTRA','The rest of Vyāsa’s work',F('Eighteen small books in rows',[(''.join(f'<g transform="translate({-80+(k%9)*20} {-(k//9)*22}) scale(.35)">{book()}</g>' for k in range(18)),1.8)],['18 Purāṇas']),['<b>Eighteen Purāṇas.</b> Tradition credits Vyāsa with the eighteen great Purāṇas, including the Bhāgavata, Viṣṇu, Śiva and Skanda Purāṇas, many quoted on this site.','<b>The Bhāgavata.</b> The Bhāgavata says Vyāsa, still unhappy after all his work, composed it at Nārada’s urging, to sing of Kṛṣṇa’s glory.','<b>Brahma Sūtra.</b> The Brahma Sūtra, the foundation text of Vedānta, is attributed to Bādarāyaṇa, often identified with Vyāsa.','<b>Scholarship.</b> Historians see these works as built by many hands over centuries; the tradition gathers them under Vyāsa’s name.'],[('z','Even Vyāsa was unhappy until he wrote about Kṛṣṇa?'),('b','So the Bhāgavata says: knowledge alone didn’t satisfy him; devotion did.')],'Purāṇas and Sūtras: <b>the library of Vyāsa</b>.'),
 R('buddhist','THE SAME FULL MOON IN OTHER TRADITIONS','Buddhists and Jains',F('A Buddha teaching five disciples under a tree',[(tree(),1.2),(person('#e0a800',seat=True),1)],['Sārnāth','']),['<b>Buddhists.</b> Buddhists remember this full moon (Āsāḷha Pūjā) as the day the Buddha gave his first sermon at Sārnāth to five disciples.','<b>Vassa.</b> It also begins the Buddhist monks’ rainy-season retreat, like Cāturmāsya.','<b>Jains.</b> Jains remember the day Mahāvīra accepted Gautama Indrabhūti as his first disciple.','<b>One idea.</b> Across traditions, the day honours the meeting of teacher and student.'],[('z','The Buddha’s first sermon too?'),('b','The same full moon. Different traditions, same honour for the teacher.')],'One full moon, <b>three traditions of teachers</b>.'),
 R('honour','HONOURING YOUR OWN TEACHERS','Simple ways',F('A student giving flowers to a teacher',[(person('#1d6fb8'),1),(lotus(),1.2),(sage('#e0a800'),1)],['student','','teacher']),['<b>Visit.</b> Visit a teacher, offer flowers or fruit, and touch their feet if that is your custom.','<b>Write.</b> Write to a teacher who shaped you, telling them so.','<b>Learn.</b> Begin or renew a study; many start a new text on Guru Pūrṇimā.','<b>Remember.</b> Remember teachers who have passed; some offer a lamp in their name.'],[('z','Can I write to an old school teacher?'),('b','Few gifts would mean more to them. That is Guru Pūrṇimā done well.')],'Visit, write, learn, remember: <b>honour your teachers</b>.')]
E[G+'the-guru/']=[
 R('qualities','WHAT MAKES A TRUE GURU','Signs in the tradition',F('A calm teacher with a lamp',[(sage('#e0a800'),1.4),(lamp(),1.4)],['','']),['<b>Learned and realised.</b> The Muṇḍaka Upaniṣad (1.2.12) says to seek a teacher who is <i>śrotriya</i> (learned in scripture) and <i>brahma-niṣṭha</i> (established in the truth).','<b>Compassion.</b> A true teacher teaches out of compassion, not for money or fame.','<b>No exploitation.</b> The tradition is clear that a teacher who exploits students is not a guru.','<b>Test and trust.</b> Students are encouraged to observe a teacher carefully before surrendering.'],[('z','How do I know a real guru?'),('b','Learning, inner peace, compassion and no exploitation. And time: watch before you trust.')],'Learned, realised, compassionate: <b>a true guru</b>.'),
 R('shishya','THE GOOD STUDENT','The other half',F('A student bowing and asking',[(person('#1d6fb8',seat=True),1.2),(sage('#e0a800'),1.2)],['śiṣya','guru']),['<b>The Gītā’s advice.</b> Gītā 4.34: learn by humble approach, by sincere questioning, and by service.','<b>Questions welcomed.</b> The tradition prizes the questioning student: Arjuna, Naciketas, Maitreyī.','<b>Śraddhā.</b> Trust and sincerity are the student’s part.','<b>Practice.</b> Knowledge is tested by living it.'],[('z','Questions are allowed?'),('b','Required! The Upaniṣads are mostly questions. Zappy, you’re in the tradition.')],'Humility, questions, service: <b>the good student</b>.'),
 R('guru-day','GURUVĀRA','Thursday',F('A golden disc for Jupiter and a teacher figure',[('<circle r="20" fill="#e0a800" stroke="#111" stroke-width="2"/>',1.6),(sage('#e0a800'),1.2)],['Guru (Jupiter)','Dakṣiṇāmūrti']),['<b>Guru’s day.</b> Thursday is Guruvāra, named after Jupiter, Bṛhaspati, the gods’ teacher.','<b>Worship.</b> In the south, Dakṣiṇāmūrti is worshipped on Thursdays; in Karnataka many visit Rāghavendra Svāmī’s shrines too.','<b>Yellow.</b> Yellow flowers and cloth are associated with Guru.','<b>Weekly reminder.</b> A weekly chance to remember one’s teachers.'],[('z','Every Thursday is a little Guru Pūrṇimā?'),('b','That’s one way to see it.')],'Thursday: <b>the teacher’s day each week</b>.')]
E[G+'chaturmasya/']=[
 R('shringeri','ŚṚṄGERI','The Śāradā Pīṭham',F('A temple by a river with a monk',[(river(200,40),1),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1),(sage('#ff8c1a'),1)],['Tuṅgā','Śāradā','Jagadguru']),['<b>Śaṅkara’s first maṭha.</b> Śṛṅgeri on the Tuṅgā in Karnataka is traditionally the first of the four maṭhas founded by Ādi Śaṅkara.','<b>Śāradā.</b> Its presiding goddess is Śāradā, Sarasvatī.','<b>The Jagadguru.</b> Its head, the Jagadguru Śaṅkarācārya, keeps Cāturmāsya with Vyāsa Pūjā, and devotees come for darśan and teaching.','<b>An unbroken line.</b> Śṛṅgeri traces an unbroken line of teachers.'],[('z','Śaṅkara founded a monastery in Karnataka?'),('b','By tradition, his first. Śṛṅgeri is one of Karnataka’s most revered places.')],'Śṛṅgeri: <b>Śaṅkara’s maṭha on the Tuṅgā</b>.'),
 R('udupi','UDUPI AND THE MĀDHVA MAṬHAS','Another lineage',F('Kṛṣṇa’s temple with eight monasteries around',[(''.join(f'<g transform="translate({-80+k*23} 0) scale(.3)"><path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/></g>' for k in range(8)),1.6)],['eight maṭhas']),['<b>Madhvācārya.</b> Udupi, founded by Madhvācārya (13th century), has the famous Kṛṣṇa temple and eight maṭhas (aṣṭa maṭha).','<b>Cāturmāsya.</b> The svāmīs of these maṭhas keep Cāturmāsya with their own observances.','<b>Paryāya.</b> The maṭhas take turns to manage the Kṛṣṇa temple, a cycle called Paryāya.','<b>Karnataka’s two great lines.</b> Śṛṅgeri (Advaita) and Udupi (Dvaita) are both in Karnataka.'],[('z','Two great traditions in one state?'),('b','And Melukōṭe for Rāmānuja’s line. Karnataka is home to all three ācāryas’ traditions.')],'Udupi: <b>Madhva’s eight maṭhas</b>.'),
 R('vrata','CĀTURMĀSYA VRATAS FOR ALL','Choosing a vow',F('A calendar with four months highlighted',[(''.join(f'<rect x="{-90+k*45}" y="-50" width="40" height="50" rx="4" fill="{"#dfe9f6" if k<4 else "#fff"}" stroke="#111"/>' for k in range(4)),1.6)],['four months']),['<b>Choose one.</b> A daily reading (the Gītā, the Bhāgavatam), a fixed japa, a lamp at the tulasī, or a food given up.','<b>Keep it small.</b> Four months is long; a small vow kept is better than a grand one abandoned.','<b>Mark it.</b> Begin with a saṅkalpa on Devaśayanī Ekādaśī or Guru Pūrṇimā.','<b>Close it.</b> End on Prabodhinī Ekādaśī with thanks.'],[('z','What would you suggest?'),('b','One chapter of the Gītā a week: eighteen weeks, almost exactly Cāturmāsya.')],'A small vow, <b>four months long</b>.'),
 R('monsoon','THE MONSOON AND THE SACRED','Why rains shape the calendar',F('Rain on fields and a closed road',[('<path d="M-40 0 q0 -20 20 -20 q10 -20 30 -10 q20 -10 30 10 q10 10 0 20z" fill="#dfe9f6" stroke="#111" stroke-width="2"/>',1.4),(tree(),1)],['rains','']),['<b>An agricultural year.</b> The Indian calendar follows the monsoon: sowing, rains, harvest.','<b>Staying put.</b> Before roads, the rains made travel dangerous; settled life invited study and vows.','<b>Festivals within.</b> Many festivals (Nāga Pañcamī, Varamahālakṣmī, Janmāṣṭamī, Gaṇeśa Caturthī) fall inside Cāturmāsya.','<b>Ending in light.</b> The season ends in Kārtika, the month of lamps.'],[('z','So the rains made the calendar?'),('b','Largely. Religion and agriculture grew up together.')],'The monsoon <b>shaped the sacred year</b>.'),
 R('teaching','LISTENING IN THE RAINS','Pravacana',F('A monk speaking to a seated audience',[(sage('#ff8c1a'),1.2),(person('#c0392b',seat=True),.9),(person('#1d6fb8',seat=True),.9)],['','','']),['<b>Discourses.</b> Where a sannyāsin stays for Cāturmāsya, daily discourses (pravacanas) are held on the Gītā, Upaniṣads or Purāṇas.','<b>Community.</b> Towns invite monks to spend Cāturmāsya with them for this reason.','<b>Questions.</b> Devotees bring questions; the season is a school.','<b>Online today.</b> Many maṭhas now share their Cāturmāsya teaching online.'],[('z','A four-month course?'),('b','Exactly that. The oldest adult-education system in India.')],'Four months of <b>listening</b>.')]
A='/festivals/akshaya-tritiya/'
E[A]=[
 R('daana','WHAT TO GIVE ON AKṢAYA TṚTĪYĀ','The traditional gifts',F('A water pot, an umbrella, sandals and a fan',[(pot('#a8553a'),1.2),('<path d="M-30 0 q30 -40 60 0z" fill="#c0392b" stroke="#111" stroke-width="2"/><path d="M0 0 v30" stroke="#111"/>',1),('<ellipse rx="20" ry="8" fill="#8a5a2a" stroke="#111"/>',1.2),('<path d="M0 0 q-20 -30 0 -40 q20 10 0 40z" fill="#e0a800" stroke="#111"/>',1)],['water pot','umbrella','sandals','fan']),['<b>Summer gifts.</b> Coming in the heat of Vaiśākha, the day’s traditional gifts are things that relieve heat: water pots, umbrellas, sandals, fans, and cool drinks.','<b>Food and grain.</b> Rice, wheat, sugar and fruit are given.','<b>Water stalls.</b> Setting up a water stall (prapā) for travellers is praised.','<b>Today.</b> Water for birds and animals in summer is a fine modern form.'],[('z','An umbrella is a holy gift?'),('b','In May? The most practical holy gift there is.')],'Gifts against the heat: <b>water, shade, cool air</b>.'),
 R('beginnings','NEW BEGINNINGS ON THE DAY','Why people start things',F('A shop opening, a child starting school, a farmer sowing',[(person('#c0392b'),1),(child(),1.2),(person('#2a9d6f'),1)],['business','learning','sowing']),['<b>All day auspicious.</b> As a <i>svayaṃsiddha muhūrta</i>, “self-auspicious time”, the whole day is good for beginnings without consulting the almanac for an hour.','<b>Weddings.</b> In some regions many weddings are held on Akṣaya Tṛtīyā.','<b>Farming.</b> Farmers in some regions begin the season’s first ploughing.','<b>Learning.</b> Some begin a new study or practice.'],[('z','No need for an astrologer that day?'),('b','That’s the point of a self-auspicious day. The whole day is a good hour.')],'A whole day <b>good for beginning</b>.')]
S='/festivals/shravana-purnima/'
E[S+'upakarma/']=[
 R('upanayana','UPANAYANA','Where the thread begins',F('A boy receiving the thread from a teacher with a fire',[(child(),1.4),(flames(),1),(sage('#e0a800'),1.1)],['the boy','fire','teacher']),['<b>The second birth.</b> Upanayana, “leading near” (to the teacher), is the rite that begins Vedic study; the boy becomes <i>dvija</i>, “twice-born”.','<b>Gāyatrī.</b> At upanayana the boy is taught the Gāyatrī mantra; see our <a href="/devi/gayatri-mantra/">Gāyatrī article</a>.','<b>Age.</b> Traditionally at 8, 11 or 12, depending on community.','<b>Upākarma renews it.</b> Every year Upākarma renews what upanayana began.'],[('z','So Upākarma is like a yearly birthday of the thread?'),('b','A yearly renewal. Upanayana is the start; Upākarma keeps it new.')],'Upanayana begins, <b>Upākarma renews</b>.'),
 R('kamokarshit','THE ATONEMENT','Kāmo’kārṣīt japa',F('A man in water reciting with folded hands',[(river(200,40),1),(person('#f4f1ea'),1)],['','']),['<b>An honest admission.</b> Part of the Upākarma rite in many traditions is a japa of a short formula admitting that desire and anger, not the self, caused one’s lapses (the <i>kāmo’kārṣīt manyur akārṣīt</i> japa).','<b>Atonement.</b> It is part of the prāyaścitta for the year’s faults.','<b>Then the bath.</b> The participants bathe and are purified.','<b>Ready to begin.</b> Only then is the new thread worn.'],[('z','“Desire did it, not me”?'),('b','A humble way of saying: I slipped, and I want to begin again clean. Every new year needs that.')],'Admit, atone, <b>begin clean</b>.'),
 R('sama','DIFFERENT DAYS FOR DIFFERENT VEDAS','Not all on one day',F('Four books with four calendar marks',[(''.join(f'<g transform="translate({-60+k*40} 0) scale(.6)">{book()}</g>' for k in range(4)),1.4)],['Ṛg · Yajur · Sāma · Atharva']),['<b>Ṛg and Yajur.</b> Followers of the Ṛg and Yajur Vedas commonly keep Upākarma on Śrāvaṇa Pūrṇimā (Yajur) or the Śravaṇa star day (Ṛg).','<b>Sāma.</b> Sāma Vedins usually keep it a month later, on the Hasta star in Bhādrapada.','<b>Local calendars.</b> Almanacs give the right day for each school.','<b>Ask.</b> Families follow their own Veda and sūtra.'],[('z','My Sāma Vedi friend changed his thread on a different day!'),('b','Exactly right for him. Each Veda has its own Upākarma day.')],'Each Veda <b>its own day</b>.'),
 R('gayatri-japa','GĀYATRĪ JAPA DAY','The day after',F('A man seated at dawn with a rosary facing the sun',[(person('#f4f1ea',seat=True),1.2),(sun(20),1)],['','']),['<b>1008 times.</b> On the day after Upākarma many recite the Gāyatrī mantra 1008 times, to atone for omissions and renew its power.','<b>At dawn.</b> Usually in the morning, after sandhyā.','<b>Sandhyā.</b> It reminds the wearer of the daily sandhyā-vandana, the twilight prayers.','<b>Our article.</b> See <a href="/devi/gayatri-mantra/">Gāyatrī</a>.'],[('z','1008 is a lot.'),('b','About two hours. Many do it together in temples or maṭhas.')],'1008 Gāyatrīs: <b>renewing the mantra</b>.'),
 R('janivara','JANIVĀRA HUṆṆIME IN KARNATAKA','The Kannada name',F('Men in a Karnataka temple changing threads',[(person('#f4f1ea',seat=True),1),(sacred_thread(),1.4),(person('#f4f1ea',seat=True),1)],['','','']),['<b>The name.</b> In Kannada Upākarma is often called <b>Janivāra Huṇṇime</b>, “thread full moon”, or Nūlu Huṇṇime.','<b>Communities.</b> Smārta, Mādhva and Śrīvaiṣṇava communities each keep it with their own priests and maṭhas.','<b>Together.</b> Many perform it together at temples or maṭhas, by a river or tank.','<b>And Rakṣā.</b> The same day, sisters tie rākhīs ('+pages.link(1,'Part 2')+').'],[('z','Thread full moon: that’s simple.'),('b','Kannada names are often the clearest.')],'Janivāra Huṇṇime: <b>the thread full moon</b>.')]
E[S+'raksha-bandhan/']=[
 R('old-rakhi','THE OLD RAKṢĀ','Priests and patrons',F('A priest tying a thread on a patron’s wrist',[(sage('#e0a800'),1.2),(rakhi(),1),(person('#1d6fb8'),1.1)],['priest','rakṣā','patron']),['<b>Before siblings.</b> In older practice a priest tied a protective thread (rakṣā-sūtra) on his patron’s wrist on Śrāvaṇa Pūrṇimā, with blessings.','<b>The Purāṇa.</b> The Bhaviṣya Purāṇa describes this, with the Indrāṇī story.','<b>Kings.</b> Royal priests tied rakṣās on kings.','<b>Still today.</b> Many priests still tie a thread on devotees on this day.'],[('z','The priest tied it, not the sister?'),('b','In the older form. Protection by blessing; the sibling form grew from it.')],'The old rakṣā: <b>a priest’s blessing</b>.'),
 R('narali','NĀRAḶĪ PŪRṆIMĀ','Coconuts for the sea',F('A fisherman offering a coconut to the waves',[(person('#1d6fb8'),1.2),('<circle r="14" fill="#8a5a2a" stroke="#111" stroke-width="2"/>',1.4),(river(200,40,'#5a8ac0'),1)],['fisherman','coconut','sea']),['<b>The coconut full moon.</b> On the western coast (Maharashtra, Goa, coastal Karnataka) fishing communities offer coconuts to the sea on this day.','<b>End of the pause.</b> It marks the end of the monsoon break in fishing; boats go out again.','<b>Varuṇa.</b> The offering is to Varuṇa, god of the waters, for safe voyages.','<b>Celebration.</b> Boats are decorated, and sweets with coconut are made.'],[('z','A coconut for the sea god?'),('b','For safe seas. Fishing families know what the sea can do.')],'Coconuts for Varuṇa: <b>safe seas</b>.'),
 R('meaning','WHAT THE THREAD MEANS','A bond that obliges',F('A thread joining two hands',[('<path d="M-60 0 q60 -30 120 0" fill="none" stroke="#c0392b" stroke-width="5"/>',1.6),(rakhi(),1)],['','']),['<b>Protection.</b> Rakṣā means protection; the thread carries a prayer for it.','<b>Obligation.</b> To accept it is to accept a duty to protect.','<b>Love.</b> Its real strength, in every story, is love.','<b>Mutual.</b> Many today see the bond as mutual: siblings protecting each other.'],[('z','A thread can make a promise?'),('b','The thread reminds; the people promise.')],'A thread that <b>reminds a promise</b>.'),
 R('karnataka','IN KARNATAKA','Rakṣā and the thread full moon',F('A sister tying a rākhī and a brother in a sacred thread',[(person('#c0392b'),1.1),(rakhi(),1),(person('#f4f1ea'),1.1)],['','','']),['<b>Both observances.</b> In Karnataka homes, men may change their sacred thread in the morning (Janivāra Huṇṇime) and receive rākhīs later.','<b>Growing custom.</b> Rakṣā Bandhan has become widely celebrated in Karnataka in recent decades.','<b>Coastal Karnataka.</b> Coastal communities add Nāraḷī Pūrṇimā’s sea offering.','<b>Sweets.</b> Local sweets accompany the rākhī.'],[('z','So Karnataka does all three?'),('b','Thread, rākhī and, on the coast, the coconut. One full moon, many bonds.')],'Thread, rākhī, coconut: <b>Karnataka’s full moon</b>.')]
D='/festivals/dhanurmasa/'
E[D+'overview/']=[
 R('margashirsha','MĀRGAŚĪRṢA, THE BEST MONTH','“Among months, I am Mārgaśīrṣa”',F('Kṛṣṇa teaching Arjuna on a chariot',[(person('#5a8ad0'),1.2),(person('#1d6fb8'),1.1)],['Kṛṣṇa','Arjuna']),['<b>The Gītā.</b> In Gītā 10.35 Kṛṣṇa says, “Among months I am Mārgaśīrṣa.”','<b>Overlap.</b> Dhanurmāsa overlaps Mārgaśīrṣa and Pauṣa in the lunar calendar.','<b>Why best.</b> Commentators note the harvest, the pleasant weather, and its position as the gods’ dawn.','<b>Gītā Jayantī.</b> The Gītā is said to have been taught in Mārgaśīrṣa, on Mokṣadā Ekādaśī.'],[('z','Kṛṣṇa picked a favourite month?'),('b','He named it as his own glory. Devotees took the hint.')],'“Among months, <b>I am Mārgaśīrṣa</b>.”'),
 R('solar','A SOLAR MONTH','Dhanus and the sun',F('The sun in the sign of the archer',[(sun(20),1.4),(bow(),1.2)],['the sun','Dhanus']),['<b>Solar, not lunar.</b> Unlike most festivals, Dhanurmāsa follows the sun: it lasts while the sun is in Dhanus (Sagittarius).','<b>Dates.</b> It therefore falls at about the same time every year, roughly mid-December to mid-January.','<b>Tamil Mārgaḻi.</b> The Tamil month Mārgaḻi is this same solar month.','<b>Ends at Saṅkrānti.</b> The sun enters Makara on Saṅkrānti, ending the month.'],[('z','So it’s on the same dates each year?'),('b','Nearly. That’s the sun for you, steady.')],'A <b>solar month</b>, mid-December to mid-January.'),
 R('vaikuntha','VAIKUṆṬHA EKĀDAŚĪ IN THE MONTH','The great day within',F('A golden gate opening',[('<path d="M-60 0 v-110 q60 -40 120 0 v110z" fill="#e0a800" stroke="#111" stroke-width="2.5"/>',1.2)],['the northern gate']),['<b>Usually inside.</b> Vaikuṇṭha (Mokṣadā) Ekādaśī usually falls within Dhanurmāsa.','<b>The gate.</b> The Vaikuṇṭha dvāra opens in Viṣṇu temples.','<b>Our article.</b> See <a href="/festivals/vaikuntha-ekadashi/">Vaikuṇṭha Ekādaśī</a> and <a href="/festivals/ekadashi/mokshada/">Mokṣadā</a>.','<b>The peak.</b> For many it is the high point of Dhanurmāsa.'],[('z','The best Ekādaśī in the best month?'),('b','Exactly why the crowds are so huge.')],'Vaikuṇṭha Ekādaśī: <b>the month’s peak</b>.'),
 R('karnataka','DHANURMĀSA IN KARNATAKA','Dawn worship across the state',F('A Karnataka temple at dawn with devotees',[(sun(16),1),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1),(person('#c0392b'),1)],['','','']),['<b>Temples.</b> Vaiṣṇava and many other temples across Karnataka hold Dhanurmāsa pūjā before sunrise.','<b>Huggi.</b> Huggi is offered and distributed ('+pages.link(3,'Part 4')+').','<b>Bhajans.</b> Groups go round streets singing before dawn in some places.','<b>Mysuru.</b> The Triraṅga and Mysuru temples keep the month; see '+pages.link(2,'Part 3')+'.'],[('z','Does Mysuru keep it?'),('b','Very much. Ask for Dhanurmāsa huggi at any Viṣṇu temple at dawn.')],'Karnataka at dawn: <b>pūjā and huggi</b>.'),
 R('meaning','WHY RISE IN THE DARK','The meaning of the month',F('A lamp before dawn with a faint sun on the horizon',[(lamp(),1.6),(sun(14),1)],['','dawn'],bg='#cfd8e6'),['<b>Before the world wakes.</b> The hour before dawn is quiet; prayer then is undistracted.','<b>The gods’ dawn.</b> Rising early in this month mirrors the gods’ own pre-dawn.','<b>Discipline.</b> Cold mornings make it a discipline.','<b>Joy.</b> And yet the month is joyful: songs, rangolis, warm food.'],[('z','Cold and joyful at once?'),('b','That’s Dhanurmāsa. Ask anyone who grew up with it.')],'Rise in the dark, <b>meet the dawn with God</b>.')]
E[D+'andal-tiruppavai/']=[
 R('alvars','THE TWELVE ĀḺVĀRS','Āṇḍāḷ’s company',F('Twelve small seated figures in a row',[(''.join(f'<g transform="translate({-110+k*20} 0) scale(.35)">{sage(["#e0a800","#2a9d6f"][k==6])}</g>' for k in range(12)),1.8)],['the Āḻvārs']),['<b>Who they are.</b> The Āḻvārs are twelve Tamil poet-saints (6th–9th centuries) whose hymns to Viṣṇu form the Nālāyira Divya Prabandham, 4,000 verses.','<b>Āṇḍāḷ.</b> She is the only woman among them, and daughter of another, Periyāḻvār.','<b>Equal to Veda.</b> Śrīvaiṣṇavas call the Prabandham the Tamil Veda.','<b>Divya Deśas.</b> The 108 temples they sang of are the Divya Deśas, holy places of Viṣṇu.'],[('z','Twelve saints, one woman?'),('b','And she is among the best loved. Her verses are sung everywhere in this month.')],'Twelve Āḻvārs, <b>one Āṇḍāḷ</b>.'),
 R('srivilliputtur','ŚRĪVILLIPUTTŪR','Āṇḍāḷ’s home',F('A tall temple tower',[('<path d="M-50 0 h100 l-16 -150 h-68z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1)],['Āṇḍāḷ’s temple']),['<b>Her town.</b> Śrīvilliputtūr in Tamil Nadu is Āṇḍāḷ’s birthplace, with her temple and the garden where she was found.','<b>The tower.</b> Its tall gopuram is the emblem of the Tamil Nadu government.','<b>Her garland.</b> Every year Āṇḍāḷ’s garland is sent to other temples, including Tirumala and Śrīraṅgam, for special days.','<b>Mārgaḻi.</b> The month is her festival.'],[('z','Her garland goes to Tirumala?'),('b','For special festivals, by tradition. The Lord still wants the garland she wore.')],'Śrīvilliputtūr: <b>where Āṇḍāḷ was found</b>.'),
 R('nacciyar','NĀCCIYĀR TIRUMOḺI','Her other song',F('A girl dreaming of a wedding procession',[(devi(sari='#2a9d6f',items=('lotus',)),1),(elephant(False),.6)],['','']),['<b>143 verses.</b> Āṇḍāḷ’s second work, the Nācciyār Tirumoḻi, is a cycle of 143 verses of longing for the Lord.','<b>Vāraṇamāyiram.</b> Its most famous section describes her dream of her wedding to Kṛṣṇa, with a thousand elephants; it is sung at Śrīvaiṣṇava weddings.','<b>Bold love.</b> Its language is passionate, a bride longing for her groom.','<b>Read with care.</b> It is mystical love poetry in the bridal tradition.'],[('z','She dreamt her own wedding?'),('b','And now families sing that dream at their own weddings.')],'Vāraṇamāyiram: <b>the dream of the wedding</b>.'),
 R('pavai','THE PĀVAI VOW','What the girls did',F('Girls bathing at dawn and making a figure from sand',[(river(200,40),1),(person('#2a9d6f'),1),(person('#e0a800'),1)],['','','']),['<b>An old custom.</b> The pāvai nōnbu was an old Tamil girls’ vow in Mārgaḻi: dawn baths and worship for rain, prosperity and a good husband.','<b>Echo of Vraja.</b> It echoes the gopīs’ Kātyāyanī vow in the same month (see <a href="/festivals/navaratri/katyayani/">Kātyāyanī</a>).','<b>Āṇḍāḷ’s twist.</b> She turns it into a vow for Kṛṣṇa himself.','<b>Today.</b> The Tiruppāvai keeps the vow alive in song.'],[('z','Like the gopīs?'),('b','Āṇḍāḷ imagined Śrīvilliputtūr as Vraja and herself as a gopī.')],'The pāvai vow: <b>dawn baths for the Lord</b>.'),
 R('singing','HOW TO SING IT','At home in the month',F('A child singing from a book at dawn',[(child(),1.4),(book(),1.2),(lamp(),1.2)],['','','']),['<b>One a day.</b> Sing the day’s verse each morning of the month.','<b>Rāga.</b> Traditional tunes (rāgas) are set for each verse; recordings are widely available.','<b>Meaning.</b> Read the meaning in our <a href="/vishnu/tiruppavai/">Tiruppāvai series</a>.','<b>Children.</b> Many children learn it in this month, one verse a day.'],[('z','Thirty verses in thirty days?'),('b','One verse a morning. By Bhogi you have the whole song.')],'One verse <b>every dawn</b>.')]
E[D+'in-temples/']=[
 R('melukote','MELUKŌṬE','Rāmānuja’s Karnataka',F('A hilltop temple',[('<path d="M-90 0 L0 -60 L90 0z" fill="#8a9a6a" stroke="#111" stroke-width="2"/>',1),('<path d="M-30 0 h60 l-10 -60 h-40z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',.8)],['Melukōṭe','']),['<b>Rāmānuja’s home.</b> Melukōṭe near Mysuru, where Rāmānuja lived for years, is Karnataka’s great Śrīvaiṣṇava centre.','<b>Dhanurmāsa.</b> The Tiruppāvai is sung there through the month.','<b>Our article.</b> See <a href="/temples-of-india/around-mysuru/melukote/">Melukōṭe</a>.','<b>Tamil in Karnataka.</b> Āṇḍāḷ’s Tamil verses are sung in a Karnataka temple: the tradition crosses languages.'],[('z','Tamil songs in Karnataka?'),('b','The Śrīvaiṣṇava tradition carries them everywhere. Melukōṭe sings them beautifully.')],'Melukōṭe: <b>Āṇḍāḷ sung near Mysuru</b>.'),
 R('pagal','PAGAL PATTU AND RĀ PATTU','Twenty days at Śrīraṅgam',F('A deity carried in procession through a hall with reciters',[(sage('#f4f1ea'),1),(vishnu(),.9),(sage('#f4f1ea'),1)],['','Namperumāḷ','']),['<b>Day ten.</b> <i>Pagal pattu</i>, the ten daytime days before Vaikuṇṭha Ekādaśī, recite the first 2,000 verses of the Prabandham.','<b>Night ten.</b> <i>Rā pattu</i>, the ten nights after, recite the rest.','<b>The deity listens.</b> Namperumāḷ, the festival image, sits in the hall and “listens” to the Āḻvārs’ hymns.','<b>Araiyars.</b> Hereditary singers (araiyars) perform the verses with gesture.'],[('z','The Lord listens to the hymns?'),('b','That’s the beautiful idea: the saints sing, and he comes out to hear.')],'Twenty days of <b>the Lord listening to his saints</b>.'),
 R('sankranti','TEMPLES AT SAṄKRĀNTI','The month’s end in temples',F('A decorated temple with sugarcane',[('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1),('<path d="M0 0 v-120" stroke="#5a8a3a" stroke-width="6"/>',1)],['','sugarcane']),['<b>Bhogi.</b> Āṇḍāḷ’s wedding on Bhogi closes the month.','<b>Saṅkrānti.</b> Temples decorate with sugarcane and offer pongal on Saṅkrānti.','<b>Cows.</b> In Tamil Nadu, Kaṇṇum/Māṭṭu Pongal honours cattle the next day.','<b>Our article.</b> See <a href="/festivals/makara-sankranti/">Makara Saṅkrānti</a>.'],[('z','The month ends with a wedding and a harvest?'),('b','A perfect ending: Āṇḍāḷ’s joy, then the harvest’s.')],'A wedding, then <b>the harvest</b>.'),
 R('visiting','VISITING IN THE MONTH','Practical notes without timings',F('Devotees in warm wraps queueing before dawn',[(person('#7a3fa0'),1),(person('#c0392b'),1),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1)],['','','']),['<b>Early.</b> Dawn worship means arriving in the dark; bring a shawl.','<b>Crowds.</b> Vaikuṇṭha Ekādaśī brings very large crowds; temples publish arrangements.','<b>Prasāda.</b> Hot pongal/huggi is often distributed after the dawn pūjā.','<b>Check.</b> Each temple announces its own schedule; we give none here.'],[('z','Bring a shawl to the temple?'),('b','December dawns are cold, even in the south!')],'Come early, <b>come warm</b>.')]
E[D+'at-home/']=[
 R('kolam-designs','KOLAM DESIGNS','Dots, loops and flowers',F('Three rangoli designs',[(kolam(),1.2),(kolam(),1.2),(kolam(),1.2)],['','',''],bg='#8a6a4a'),['<b>Pulli kolam.</b> Dot kolams: a grid of dots with lines looping round them, often in one continuous line.','<b>Kambi kolam.</b> Line kolams of interlocking curves.','<b>Coloured rangoli.</b> In Karnataka, rangoli is often coloured with powders, especially in Dhanurmāsa and for Saṅkrānti.','<b>Learning.</b> Girls (and boys) learn kolams from mothers and grandmothers, a living art.'],[('z','One continuous line?'),('b','Some kolams never lift the hand. A meditation in rice flour.')],'Dots and loops: <b>a living art</b>.'),
 R('huggi-recipe','MAKING KHĀRA HUGGI','The basic idea',F('A pot of rice and dal with pepper, cumin and ghee',[(pot_rice(),1.6),('<circle r="6" fill="#111"/>',1),('<circle r="6" fill="#e0a800"/>',1)],['huggi','pepper','ghee']),['<b>Rice and dal.</b> Rice and split moong dal, often lightly roasted, are cooked soft together.','<b>Tempering.</b> Ghee is heated with black pepper, cumin, ginger, curry leaves and cashews, and poured over.','<b>Sihi huggi.</b> The sweet version adds jaggery, coconut and cardamom.','<b>Offered first.</b> At home, it is offered to the Lord at dawn before anyone eats.'],[('z','That sounds easy!'),('b','It is. The secret is ghee and patience.')],'Rice, dal, pepper, ghee: <b>huggi</b>.'),
 R('kitchen','THE KITCHEN BEFORE DAWN','A household’s month',F('A kitchen lamp lit before dawn',[(lamp(),1.6),(pot_rice(),1.4)],['','']),['<b>Early stove.</b> In homes that keep the month, the stove is lit before dawn to cook the offering.','<b>Family worship.</b> The family gathers for a short pūjā and the day’s Tiruppāvai verse.','<b>School and work.</b> Then the day begins, on a warm meal.','<b>A memory.</b> Many grown-ups remember Dhanurmāsa mornings as among their happiest.'],[('z','Even before school?'),('b','Especially. You go to school warm and blessed.')],'The stove lit <b>before dawn</b>.'),
 R('no-ceremonies-home','WHAT WAITS UNTIL SAṄKRĀNTI','Plans for after',F('A calendar page turning to the sun in Makara',[(sun(20),1.4)],['Makara']),['<b>Weddings.</b> Families plan weddings for after Saṅkrānti.','<b>House-warmings.</b> Gṛha-praveśa is held after the month.','<b>New ventures.</b> Some postpone major new starts.','<b>Not fear.</b> This is not because the month is unlucky, but because it is given to God.'],[('z','So all the weddings happen in January?'),('b','Quite a few! The season opens right after.')],'Ceremonies <b>wait for the sun’s turn</b>.'),
 R('ellu','EḶḶU-BELLA AND SAṄKRĀNTI','Karnataka’s ending',F('A plate of sesame, jaggery, coconut and sugar figures',[('<ellipse rx="50" ry="12" fill="#e8c06a" stroke="#111"/>'+''.join(f'<circle cx="{x}" cy="-6" r="5" fill="{c}"/>' for x,c in [(-24,'#f3e3c3'),(-8,'#a8553a'),(8,'#fff'),(24,'#e0a800')]),1.6)],['eḷḷu-bella']),['<b>Eḷḷu-bella.</b> At Saṅkrānti Karnataka families exchange <b>eḷḷu-bella</b>: sesame, jaggery, dried coconut, peanuts and fried gram, with sugar figures (sakkare acchu).','<b>The saying.</b> “Eḷḷu-bella tinda oḷḷe mātāḍi”: eat sesame and jaggery, speak sweetly.','<b>Eḷḷu bīroduu.</b> Children go house to house giving eḷḷu, a beloved custom.','<b>Cattle.</b> In villages cattle are decorated and made to jump over fire (kicchu hāyisuvudu).'],[('z','Speak sweetly after eating sweets?'),('b','That’s the whole message: begin the new solar year with sweet words.')],'Eat sesame and jaggery, <b>speak sweetly</b>.')]
runpy.run_path('misc.py')
print('extras2 done')
